import { test as _unused, expect, expectStatus, test, type Document, type DocumentKind } from "../../fixtures";

test("the re-uploaded W-9 is the one sent to review, and both uploads stay listed oldest first", { tag: "@LIF-01" }, async ({ apiAs, factory }) => {
  // Arrange: a draft vendor with the two documents that don't change in this scenario.
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate.txt", "member");
  await factory.upload(vendor.id, "contract", "contract.txt", "member");

  // Arrange: two W-9 uploads with different legal names, the second one replacing the first.
  const uploadW9 = async (legalName: string): Promise<Document> => {
    const text = `Legal Name: ${legalName}\nTax ID: 84-2219067\nBusiness Type: LLC\n`;
    const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9" satisfies DocumentKind,
        file: { name: `w9-${legalName.replace(/\W+/g, "-")}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
      },
    });
    return expectStatus<Document>(response, 201);
  };
  const firstW9 = await uploadW9("First Name LLC");
  const secondW9 = await uploadW9("Second Name LLC");

  // Arrange: wait for all four documents to finish extraction, then submit.
  await expect
    .poll(
      async () => {
        const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return docs.map((d) => d.status);
      },
      { message: "all four documents are extracted", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted", "extracted"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // Act: a reviewer opens the review queue.
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<
    { vendor_id: string; extractions: { kind: string; fields: Record<string, { value: string | null }> }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);

  // Assert: the vendor's W-9 extraction in the queue carries the second upload's legal name.
  const item = queue.find((entry) => entry.vendor_id === vendor.id);
  expect(item, "submitted vendor appears in the review queue").toBeDefined();
  const queuedW9 = item!.extractions.filter((e) => e.kind === "w9");
  expect(queuedW9.map((e) => e.fields.legal_name?.value)).toEqual(["Second Name LLC"]);

  // Assert: the documents list keeps both W-9 uploads, oldest first.
  const documents = await expectStatus<(Document & { created_at: string })[]>(
    await member.get(`/api/vendors/${vendor.id}/documents`),
    200,
  );
  const w9s = documents.filter((d) => d.kind === "w9");
  expect(w9s.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
  const times = w9s.map((d) => Date.parse(d.created_at));
  expect(times).toEqual([...times].sort((a, b) => a - b));
});
